-- Backend Engineering ("The Fracture") Act 15 -- "RPC & Realtime" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql)
-- and Act 6 (20260810090000_backend_act6_content.sql).
-- References world-be-15, whose narrative metadata was pre-authored in
-- 20260810140000_backend_acts11_15_and_arc3.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be15', 'world-be-15', 'rpc-and-realtime', '15A - RPC & Realtime', 'The transit dashboard needs live vehicle positions, not a page someone refreshes -- and the service feeding it keeps going dark without telling anyone.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be15-1', 'campaign-be15', 'speaking-in-contracts', 'Speaking in Contracts', 'Remote calls that look local, and the strict binary contract that makes them fast and safe.', 1),
  ('operation-be15-2', 'campaign-be15', 'the-live-feed', 'The Live Feed', 'Deadlines, metadata, and the browser-facing protocols that keep a live feed honest about whether it is actually still live.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be15-01', 'world-be-15', 'campaign-be15', 'operation-be15-1', 'rpc-fundamentals', 'RPC Fundamentals', 'The transit team wants live vehicle positions on the dashboard, not a page somebody refreshes. Forge Division reaches for a pattern older than REST: make a remote call look and feel like a local one.', 'intermediate', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"rpc-fundamentals-sim"}'::jsonb, '{"xp":195,"credits":35}'::jsonb, false, 1),
  ('mission-be15-02', 'world-be-15', 'campaign-be15', 'operation-be15-1', 'protocol-buffers', 'Protocol Buffers', 'Before two services can call each other reliably, they need to agree -- exactly, down to the byte -- on the shape of what they''re sending. That agreement has a name.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be15-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"protobuf-schema-sim"}'::jsonb, '{"xp":200,"credits":36}'::jsonb, false, 2),
  ('mission-be15-03', 'world-be-15', 'campaign-be15', 'operation-be15-1', 'grpc-services', 'gRPC Services', 'Protocol Buffers define the data. gRPC is the framework that turns that definition into a working service, running over the same HTTP/2 the rest of the city already trusts.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be15-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"grpc-service-sim"}'::jsonb, '{"xp":205,"credits":37}'::jsonb, false, 3),
  ('mission-be15-04', 'world-be-15', 'campaign-be15', 'operation-be15-1', 'unary-calls', 'Unary Calls', 'The simplest shape gRPC offers: one request, one response, gone the moment it arrives. Perfect for a single lookup. Not remotely enough for a bus that will not stop moving.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be15-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"unary-call-sim"}'::jsonb, '{"xp":208,"credits":37}'::jsonb, false, 4),
  ('mission-be15-05', 'world-be-15', 'campaign-be15', 'operation-be15-1', 'server-streaming', 'Server Streaming', 'One request opens a channel; the server keeps talking as long as there is something new to say. This is the shape the vehicle-position feed actually needed all along.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be15-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"server-streaming-sim"}'::jsonb, '{"xp":215,"credits":38}'::jsonb, false, 5),
  ('mission-be15-06', 'world-be-15', 'campaign-be15', 'operation-be15-1', 'client-and-bidirectional-streaming', 'Client and Bidirectional Streaming Concepts', 'Streams do not have to run in only one direction. Learn the two remaining shapes before deciding which one -- if any -- this feed actually needs.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be15-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"streaming-shapes-sim"}'::jsonb, '{"xp":220,"credits":39}'::jsonb, false, 6),
  ('mission-be15-07', 'world-be-15', 'campaign-be15', 'operation-be15-2', 'deadlines-and-metadata', 'Deadlines and Metadata', 'A call that never comes back is not a success waiting to happen -- it is a resource silently held forever. Learn the two tools that keep a call honest about its own limits.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be15-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"deadlines-metadata-sim"}'::jsonb, '{"xp":222,"credits":39}'::jsonb, false, 7),
  ('mission-be15-08', 'world-be-15', 'campaign-be15', 'operation-be15-2', 'rest-vs-graphql-vs-grpc', 'REST vs GraphQL vs gRPC', 'Three ways to ask a service for something, learned across three different Acts. None of them is universally right. Learn to pick.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be15-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"protocol-tradeoffs-sim"}'::jsonb, '{"xp":225,"credits":40}'::jsonb, false, 8),
  ('mission-be15-09', 'world-be-15', 'campaign-be15', 'operation-be15-2', 'websockets', 'WebSockets', 'gRPC does not run in a browser tab. For the dashboard itself, the city needs a different kind of always-open connection -- and it is the one that keeps quietly going dark.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be15-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"websocket-handshake-sim"}'::jsonb, '{"xp":228,"credits":40}'::jsonb, false, 9),
  ('mission-be15-10', 'world-be-15', 'campaign-be15', 'operation-be15-2', 'server-sent-events', 'Server-Sent Events', 'Not every live feed needs two-way traffic. Sometimes the browser only ever needs to listen, and a simpler protocol built on plain HTTP will do.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be15-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"sse-stream-sim"}'::jsonb, '{"xp":230,"credits":41}'::jsonb, false, 10),
  ('mission-be15-11', 'world-be-15', 'campaign-be15', 'operation-be15-2', 'reconnect-and-presence', 'Reconnect and Presence', 'A connection can vanish without anyone saying goodbye. Learn how a well-built client reconnects, and how a well-built service actually notices someone left.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be15-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"reconnect-presence-sim"}'::jsonb, '{"xp":233,"credits":42}'::jsonb, false, 11),
  ('mission-be15-12', 'world-be-15', 'campaign-be15', 'operation-be15-2', 'the-disconnected-city', 'The Disconnected City', 'A bus went dark and the dashboard called it "on time" for eleven minutes. Every safeguard this Act taught, aimed at the one the feed never actually had.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be15-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"disconnected-city-boss-sim"}'::jsonb, '{"xp":500,"credits":110,"badgeIds":["disconnected-city"],"skillXp":{"realtime_systems":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be15-01', 1, 'mira', 'The transit team has a simple request that turns out not to be simple at all: they want live vehicle positions on the dashboard. Not a page a dispatcher refreshes every ten seconds -- actually live.'),
  ('mission-be15-01', 2, 'forge', 'REST is built around asking a question and getting one answer. Position updates are a stream of small, frequent, structured facts flying between services that already trust each other. That is a different kind of problem.'),
  ('mission-be15-01', 3, 'mira', 'So we are reaching for something older than REST, and in some ways simpler: Remote Procedure Calls. Make calling a function on another machine feel, from the code''s point of view, almost exactly like calling one on your own.'),
  ('mission-be15-01', 4, 'forge', 'Almost. The illusion has edges, and every incident in this Act happens right at one of them. Start with what RPC actually promises, and what it quietly does not.'),
  ('mission-be15-02', 1, 'forge', 'An RPC call is only as trustworthy as the agreement both sides have about what is being sent. Loose JSON got us this far. It will not get us through a service sending vehicle updates dozens of times a second.'),
  ('mission-be15-02', 2, 'forge', 'Protocol Buffers -- protobuf -- is Google''s answer: a strict, typed schema both sides compile from, and a compact binary format on the wire instead of readable-but-bulky text.'),
  ('mission-be15-03', 1, 'mira', 'Protobuf defines the data. gRPC is what turns that definition into an actual running service -- method signatures, generated client and server code, and HTTP/2 doing the transport underneath.'),
  ('mission-be15-03', 2, 'mira', 'Every gRPC service you will ever read is really just four possible shapes of conversation. Today, meet all four before you commit to one for this dashboard.'),
  ('mission-be15-04', 1, 'forge', 'Start with the simplest shape: unary. One request goes out, one response comes back, and the call is over. It is a gRPC call that behaves almost exactly like calling a local function that happens to take a moment.'),
  ('mission-be15-04', 2, 'forge', 'Ask yourself, honestly, whether that shape can carry a bus''s position for the next six hours without the dashboard falling back to polling it every few seconds anyway.'),
  ('mission-be15-05', 1, 'mira', 'Server streaming answers the problem unary could not: one request opens the channel, and the server keeps sending new messages down it for as long as there is something worth reporting.'),
  ('mission-be15-05', 2, 'mira', 'This is the shape the transit feed actually needed from day one. Learn exactly how the channel opens, stays open, and is supposed to close.'),
  ('mission-be15-06', 1, 'forge', 'Two shapes left. Client streaming flips server streaming around: the client keeps sending, the server answers once, at the end. Bidirectional streaming lets both sides send whenever they want, independently, on the same connection.'),
  ('mission-be15-06', 2, 'forge', 'None of the three streaming shapes is automatically ''the right one.'' Each buys you something specific and costs you something specific in return.'),
  ('mission-be15-07', 1, 'mira', 'A call that never returns is not neutral. It ties up a connection, a thread, a slot in a connection pool, forever, unless something forces it to stop. That something is a deadline.'),
  ('mission-be15-07', 2, 'mira', 'Metadata is the other half of the picture -- the key-value pairs riding alongside a call, the way headers ride alongside an HTTP request. Auth tokens, trace IDs, and yes, sometimes the deadline itself.'),
  ('mission-be15-08', 1, 'forge', 'Zoom out. You have now learned three different ways to ask a service for something: REST, back in Act 1. GraphQL, in the district next door. gRPC, this Act. Time to actually compare them instead of just knowing them.'),
  ('mission-be15-08', 2, 'forge', 'There is no universally correct answer here. There is only ''correct for this specific call, between these specific things, for this specific reason.'''),
  ('mission-be15-09', 1, 'mira', 'Here is the part gRPC cannot do for us: it does not run in a browser tab, not without extra plumbing most dashboards do not bother with. The transit dashboard itself needs a different always-open connection.'),
  ('mission-be15-09', 2, 'mira', 'WebSockets. A single TCP connection, upgraded once from an ordinary HTTP request, that then stays open and lets both sides send whenever they want. This is also, not coincidentally, the exact connection that keeps quietly going dark on us.'),
  ('mission-be15-10', 1, 'forge', 'Not everything needs two-way traffic. A stock ticker, a live scoreboard, a feed of vehicle positions the browser only ever reads -- sometimes the browser just needs to listen, and forcing a full WebSocket on that is more than the job requires.'),
  ('mission-be15-10', 2, 'forge', 'Server-Sent Events run over plain HTTP, the browser''s EventSource API handles the connection for you, and reconnection after a drop is automatic -- built into the browser, not something you have to hand-roll.'),
  ('mission-be15-11', 1, 'mira', 'Automatic reconnection is not the same thing as fast, safe reconnection. Reconnect carelessly and you can hammer a struggling service with retries at the exact moment it least needs them.'),
  ('mission-be15-11', 2, 'mira', 'And reconnection only matters once you know a connection is actually gone. That is presence: the ongoing, active question of ''is the other side still really there,'' asked by something other than hope.'),
  ('mission-be15-12', 1, 'mira', 'Here is the incident. A transit dashboard bus icon sat labeled "on time" for eleven minutes after that bus''s vehicle service had actually gone completely dark.'),
  ('mission-be15-12', 2, 'forge', 'The WebSocket connection feeding that bus''s updates dropped somewhere along the way. Nothing crashed. No error was logged. The dashboard simply stopped hearing from it -- and kept showing the last thing it was ever told.'),
  ('mission-be15-12', 3, 'mira', 'I have three explanations on the table for why nobody -- and nothing -- noticed for eleven whole minutes. Judge each one on whether it actually explains the gap, or just sounds like it should.'),
  ('mission-be15-12', 4, 'forge', '...one more thing, while you work. Every one of these dropped connections shares the exact same reconnect handshake. And that handshake''s log has a doubled path segment in it: /realtime//vehicle-feed. Same mark. Still not today''s bug.'),
  ('mission-be15-12', 5, 'mira', 'Filed, same as always. It is not the day we chase that thread -- but real-time, low-latency links between services now run city-wide, which means when something breaks next, it will not have the courtesy of staying inside one service.'),
  ('mission-be15-12', 6, 'forge', 'Background work and queues are next on the list. For today: find the safeguard this feed never had.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be15-01-o1', 'mission-be15-01', 1, 'Name what RPC actually buys you', 'Decide what a Remote Procedure Call is actually promising to hide from the caller.'),
  ('mission-be15-01-o2', 'mission-be15-01', 2, 'Match the RPC concept', 'Match each RPC building block to what it actually does.'),
  ('mission-be15-02-o1', 'mission-be15-02', 1, 'Match the protobuf concept', 'Match each .proto element to what it actually defines.'),
  ('mission-be15-02-o2', 'mission-be15-02', 2, 'Find the schema bug', 'Find the line that would corrupt data on the wire the moment this schema ships.'),
  ('mission-be15-03-o1', 'mission-be15-03', 1, 'Name the combination', 'Decide what gRPC actually is, underneath the name.'),
  ('mission-be15-03-o2', 'mission-be15-03', 2, 'Match the four shapes', 'Match each RPC method shape to what actually happens during the call.'),
  ('mission-be15-04-o1', 'mission-be15-04', 1, 'Read the unary definition', 'Find the rpc line in this service definition that is a plain unary call.'),
  ('mission-be15-04-o2', 'mission-be15-04', 2, 'Judge the fit', 'Decide whether a unary call is the right shape for a bus that never stops moving.'),
  ('mission-be15-05-o1', 'mission-be15-05', 1, 'Order the server-streaming call', 'Put the lifecycle of a server-streaming RPC call in order.'),
  ('mission-be15-05-o2', 'mission-be15-05', 2, 'Confirm the fit', 'Find the evidence that confirms server streaming actually solves the dashboard''s problem.'),
  ('mission-be15-06-o1', 'mission-be15-06', 1, 'Match the shape to the scenario', 'Match each real scenario to the streaming shape it actually needs.'),
  ('mission-be15-06-o2', 'mission-be15-06', 2, 'Read the bidirectional guarantee', 'Decide what bidirectional streaming actually guarantees about the order messages arrive in.'),
  ('mission-be15-07-o1', 'mission-be15-07', 1, 'Diagnose the hung call', 'Find the evidence that explains why a stalled call kept a resource held forever.'),
  ('mission-be15-07-o2', 'mission-be15-07', 2, 'Tell deadlines and metadata apart', 'Match each concept to the job it actually does.'),
  ('mission-be15-08-o1', 'mission-be15-08', 1, 'Match the protocol to the job', 'Match each situation to the protocol actually best suited to it.'),
  ('mission-be15-08-o2', 'mission-be15-08', 2, 'Spot gRPC''s blind spot', 'Decide what actually stops a browser tab from calling a gRPC service directly.'),
  ('mission-be15-09-o1', 'mission-be15-09', 1, 'Order the WebSocket handshake', 'Put the steps of opening a WebSocket connection in order.'),
  ('mission-be15-09-o2', 'mission-be15-09', 2, 'Find the silent gap', 'Find the evidence that explains why a WebSocket connection can vanish without either side sending a close frame.'),
  ('mission-be15-10-o1', 'mission-be15-10', 1, 'Choose SSE or WebSocket', 'Decide which protocol actually fits a server-to-client-only feed.'),
  ('mission-be15-10-o2', 'mission-be15-10', 2, 'Read the event stream', 'Find the line in this client code that explains why position updates never reach the map.'),
  ('mission-be15-11-o1', 'mission-be15-11', 1, 'Order the reconnect strategy', 'Put a well-behaved exponential-backoff reconnect strategy in order.'),
  ('mission-be15-11-o2', 'mission-be15-11', 2, 'Match the presence mechanism', 'Match each concept to what it actually does in detecting whether a connection is genuinely still alive.'),
  ('mission-be15-12-o1', 'mission-be15-12', 1, 'Diagnosis Alpha', 'Judge whether this explanation actually accounts for the eleven-minute gap.'),
  ('mission-be15-12-o2', 'mission-be15-12', 2, 'Diagnosis Bravo', 'Judge whether this explanation actually accounts for the eleven-minute gap.'),
  ('mission-be15-12-o3', 'mission-be15-12', 3, 'Diagnosis Charlie', 'Judge whether this explanation actually accounts for the eleven-minute gap.'),
  ('mission-be15-12-o4', 'mission-be15-12', 4, 'Fix the feed', 'State the one safeguard that would have caught this the moment it happened.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be15-01-o1-c1', 'mission-be15-01-o1', 1, 'multiple_choice', 'From the calling code''s point of view, what is RPC actually trying to make disappear?', '{"question":"From the calling code''s point of view, what is RPC actually trying to make disappear?","options":[{"id":"a","text":"The existence of the network call entirely -- the call looks and behaves exactly like invoking a plain local function"},{"id":"b","text":"The need for any kind of schema or contract between client and server"},{"id":"c","text":"The possibility that the call could ever fail"},{"id":"d","text":"The need for the server to run as a separate process"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be15-01-o2-c1', 'mission-be15-01-o2', 1, 'drag_and_drop', 'Match each RPC building block to what it actually does.', '{"items":[{"id":"i1","text":"Client stub"},{"id":"i2","text":"Marshalling"},{"id":"i3","text":"Transport"},{"id":"i4","text":"Server skeleton"}],"targets":[{"id":"t1","label":"Looks like a normal local function to the calling code, but actually packages up the call and sends it over the network"},{"id":"t2","label":"Converts an in-memory call (arguments, method name) into bytes that can travel over the network"},{"id":"t3","label":"The actual network layer/connection the serialized call travels across"},{"id":"t4","label":"Receives the bytes on the server side, unpacks them, and calls the real method being requested"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be15-02-o1-c1', 'mission-be15-02-o1', 1, 'drag_and_drop', 'Match each .proto element to what it actually defines.', '{"items":[{"id":"i1","text":"message"},{"id":"i2","text":"field number (the \"= 1\" after a field)"},{"id":"i3","text":"service"},{"id":"i4","text":"generated stub code"}],"targets":[{"id":"t1","label":"A typed, named data structure -- the schema for one unit of data"},{"id":"t2","label":"The unique tag written onto the wire instead of the field''s name, so renaming a field never breaks compatibility"},{"id":"t3","label":"A named collection of RPC methods a server exposes"},{"id":"t4","label":"The client and server classes protoc produces from the .proto file, so nobody hand-writes serialization code"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be15-02-o2-c1', 'mission-be15-02-o2', 1, 'code_debugging', 'Two fields in this message share the same field number. Which line is the duplicate that will collide with latitude on the wire?', '{"language":"protobuf","code":"message VehiclePosition {\n  string vehicle_id = 1;\n  double latitude = 2;\n  double longitude = 2;\n  int64 updated_at_ms = 4;\n}","question":"Two fields in this message share the same field number. Which line is the duplicate that will collide with latitude on the wire?"}'::jsonb, '{"requiredLineIds":["  double longitude = 2;"]}'::jsonb),

  ('mission-be15-03-o1-c1', 'mission-be15-03-o1', 1, 'multiple_choice', 'What is gRPC, precisely?', '{"question":"What is gRPC, precisely?","options":[{"id":"a","text":"A brand-new network protocol that replaces TCP"},{"id":"b","text":"A framework that combines Protocol Buffers for the data contract, generated client/server code, and HTTP/2 for transport"},{"id":"c","text":"A JSON-based alternative to REST"},{"id":"d","text":"A database query language"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be15-03-o2-c1', 'mission-be15-03-o2', 1, 'drag_and_drop', 'Match each RPC method shape to what actually happens during the call.', '{"items":[{"id":"i1","text":"Unary"},{"id":"i2","text":"Server streaming"},{"id":"i3","text":"Client streaming"},{"id":"i4","text":"Bidirectional streaming"}],"targets":[{"id":"t1","label":"One request in, one response out, call ends"},{"id":"t2","label":"One request in, a sequence of responses out over time"},{"id":"t3","label":"A sequence of requests in, one response out at the end"},{"id":"t4","label":"Both sides send messages independently, whenever they want, on the same open call"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be15-04-o1-c1', 'mission-be15-04-o1', 1, 'code_debugging', 'Which rpc line takes a single request and returns a single response, with no stream keyword anywhere in it?', '{"language":"protobuf","code":"service VehicleService {\n  rpc GetCurrentPosition(VehicleRequest) returns (VehiclePosition);\n  rpc StreamPositions(VehicleRequest) returns (stream VehiclePosition);\n  rpc ReportRoute(stream RouteSegment) returns (RouteSummary);\n}","question":"Which rpc line takes a single request and returns a single response, with no stream keyword anywhere in it?"}'::jsonb, '{"requiredLineIds":["  rpc GetCurrentPosition(VehicleRequest) returns (VehiclePosition);"]}'::jsonb),
  ('mission-be15-04-o2-c1', 'mission-be15-04-o2', 1, 'investigation', 'Which piece of evidence is the real reason a unary call is the wrong shape here?', '{"evidence":[{"id":"ev1","label":"Unary call trace","detail":"Dashboard calls GetCurrentPosition once, gets one position, the call ends immediately"},{"id":"ev2","label":"Dashboard requirement","detail":"The map marker needs to move continuously as the bus moves, not just once per click"},{"id":"ev3","label":"Naive workaround","detail":"Engineers considered calling GetCurrentPosition again every 2 seconds in a loop to fake continuous updates"}],"question":"Which piece of evidence is the real reason a unary call is the wrong shape here?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be15-05-o1-c1', 'mission-be15-05-o1', 1, 'interactive_diagram', 'Put the lifecycle of a server-streaming RPC call in order.', '{"diagramId":"server-streaming-lifecycle","hotspots":[{"id":"client_sends_request","label":"Client sends a single request","explanation":"One request opens the call, exactly like a unary call would."},{"id":"server_opens_stream","label":"Server accepts and opens a response stream","explanation":"Instead of returning once, the server keeps the call open to send more."},{"id":"server_sends_messages","label":"Server sends messages as they become available","explanation":"Each new vehicle position gets pushed down the same open call, no new request needed."},{"id":"server_closes_stream","label":"Server closes the stream","explanation":"The server signals there is nothing more to send, and the call formally ends."}],"task":"Put the lifecycle of a server-streaming RPC call in order."}'::jsonb, '{"correctOrderIds":["client_sends_request","server_opens_stream","server_sends_messages","server_closes_stream"]}'::jsonb),
  ('mission-be15-05-o2-c1', 'mission-be15-05-o2', 1, 'investigation', 'Which piece of evidence shows server streaming is actually solving the right problem, not just a different way to poll?', '{"evidence":[{"id":"ev1","label":"Call trace","detail":"Dashboard opens one StreamPositions call per bus and keeps receiving new VehiclePosition messages on it for hours"},{"id":"ev2","label":"Network usage","detail":"One long-lived HTTP/2 stream per bus, instead of a new connection for every position update"},{"id":"ev3","label":"Team note","detail":"Someone suggested using unary calls in a loop instead, polling every 500ms"}],"question":"Which piece of evidence shows server streaming is actually solving the right problem, not just a different way to poll?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be15-06-o1-c1', 'mission-be15-06-o1', 1, 'drag_and_drop', 'Match each real scenario to the streaming shape it actually needs.', '{"items":[{"id":"i1","text":"A bus uploads a continuous trail of GPS pings over its whole route, and the server sends back one route-summary report at the end"},{"id":"i2","text":"A dispatcher and a driver exchange live messages back and forth in the same session, either one able to speak at any moment"},{"id":"i3","text":"A dashboard requests a single bus''s current position once and gets exactly one answer"},{"id":"i4","text":"A dashboard opens one call and receives a new position every time the bus moves"}],"targets":[{"id":"t1","label":"Client streaming"},{"id":"t2","label":"Bidirectional streaming"},{"id":"t3","label":"Unary"},{"id":"t4","label":"Server streaming"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be15-06-o2-c1', 'mission-be15-06-o2', 1, 'multiple_choice', 'In a bidirectional streaming call, must the client and server strictly alternate -- one sends, then the other, back and forth?', '{"question":"In a bidirectional streaming call, must the client and server strictly alternate -- one sends, then the other, back and forth?","options":[{"id":"a","text":"Yes, gRPC enforces strict alternation"},{"id":"b","text":"No -- both sides read and write independently over the same open call; either side can send at any time, in any order, unless the application itself imposes a protocol on top"},{"id":"c","text":"No, only the client is allowed to initiate messages"},{"id":"d","text":"Bidirectional streaming does not actually allow simultaneous sending"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be15-07-o1-c1', 'mission-be15-07-o1', 1, 'investigation', 'Which piece of evidence explains why that connection-pool slot was never freed?', '{"evidence":[{"id":"ev1","label":"Call code","detail":"client.StreamPositions(request) is invoked with no deadline or timeout configured anywhere"},{"id":"ev2","label":"Connection pool metrics","detail":"A connection-pool slot has been held by the same in-flight call for over six hours, with no data received in that time"},{"id":"ev3","label":"Server load","detail":"The server handling that call is otherwise healthy and responsive to every other client"}],"question":"Which piece of evidence explains why that connection-pool slot was never freed?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),
  ('mission-be15-07-o2-c1', 'mission-be15-07-o2', 1, 'drag_and_drop', 'Match each concept to the job it actually does.', '{"items":[{"id":"i1","text":"Deadline"},{"id":"i2","text":"Metadata"},{"id":"i3","text":"Auth token"},{"id":"i4","text":"Trace/request ID"}],"targets":[{"id":"t1","label":"A hard limit on how long a call may take before the caller gives up and frees its resources automatically"},{"id":"t2","label":"The general mechanism -- key-value pairs traveling alongside a call, similar to HTTP headers, not part of the typed request message"},{"id":"t3","label":"A common thing carried as metadata so the server can verify who is calling without it being part of the business payload"},{"id":"t4","label":"A common thing carried as metadata so a request can be traced across multiple services in a log"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be15-08-o1-c1', 'mission-be15-08-o1', 1, 'drag_and_drop', 'Match each situation to the protocol actually best suited to it.', '{"items":[{"id":"i1","text":"A public API serving many different client apps that each need very different combinations of fields"},{"id":"i2","text":"A simple public resource with predictable CRUD operations and a need for HTTP caching"},{"id":"i3","text":"High-throughput, low-latency calls between two internal services that fully control both ends"},{"id":"i4","text":"A live feed of many small updates pushed continuously from server to internal consumer"}],"targets":[{"id":"t1","label":"GraphQL"},{"id":"t2","label":"REST"},{"id":"t3","label":"gRPC (unary)"},{"id":"t4","label":"gRPC (server streaming)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be15-08-o2-c1', 'mission-be15-08-o2', 1, 'multiple_choice', 'A browser tab cannot call a plain gRPC service directly the way it can call a REST or GraphQL endpoint. Why not?', '{"question":"A browser tab cannot call a plain gRPC service directly the way it can call a REST or GraphQL endpoint. Why not?","options":[{"id":"a","text":"gRPC is slower than REST, so browsers block it"},{"id":"b","text":"Browsers cannot construct the raw HTTP/2 frames and binary protobuf gRPC needs, and lack full control over trailers -- a browser needs a compatibility layer such as grpc-web and a proxy in front of the real gRPC service"},{"id":"c","text":"gRPC only works over unencrypted connections, which browsers refuse"},{"id":"d","text":"gRPC requires a database connection the browser does not have"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be15-09-o1-c1', 'mission-be15-09-o1', 1, 'interactive_diagram', 'Put the steps of opening a WebSocket connection in order.', '{"diagramId":"websocket-handshake","hotspots":[{"id":"http_get_upgrade","label":"Client sends an HTTP GET with an Upgrade: websocket header","explanation":"The connection starts as a completely ordinary HTTP request."},{"id":"switching_protocols","label":"Server responds 101 Switching Protocols","explanation":"The server agrees, and the same underlying TCP connection is repurposed instead of a new one being opened."},{"id":"full_duplex_frames","label":"Both sides exchange frames freely","explanation":"From here on, either side can send a message at any time, without waiting for a request/response cycle."},{"id":"close_frame","label":"Either side sends a close frame","explanation":"A proper shutdown is negotiated explicitly -- it is not supposed to just vanish."}],"task":"Put the steps of opening a WebSocket connection in order."}'::jsonb, '{"correctOrderIds":["http_get_upgrade","switching_protocols","full_duplex_frames","close_frame"]}'::jsonb),
  ('mission-be15-09-o2-c1', 'mission-be15-09-o2', 1, 'investigation', 'Which piece of evidence best explains why a connection can go dark with no close frame and no error on either side?', '{"evidence":[{"id":"ev1","label":"Network topology note","detail":"The dashboard''s WebSocket traffic passes through a mobile network, a load balancer, and a NAT gateway before reaching the server"},{"id":"ev2","label":"Connection close log","detail":"Searching server logs for a close frame from the affected bus''s connection returns nothing at all"},{"id":"ev3","label":"App design note","detail":"The WebSocket handler never sends anything unless there is new position data to report"}],"question":"Which piece of evidence best explains why a connection can go dark with no close frame and no error on either side?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be15-10-o1-c1', 'mission-be15-10-o1', 1, 'multiple_choice', 'The vehicle-position feed only ever needs to push data from server to browser -- the browser never needs to send anything back on that same channel. Which is the better-fitting choice, and why?', '{"question":"The vehicle-position feed only ever needs to push data from server to browser -- the browser never needs to send anything back on that same channel. Which is the better-fitting choice, and why?","options":[{"id":"a","text":"WebSocket, because it is newer"},{"id":"b","text":"Server-Sent Events -- it is simpler to operate, runs over plain HTTP, and the browser''s EventSource API reconnects automatically, since the extra bidirectional capability of a WebSocket is not being used anyway"},{"id":"c","text":"Neither -- this should be plain polling"},{"id":"d","text":"WebSocket, because SSE cannot carry JSON payloads"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be15-10-o2-c1', 'mission-be15-10-o2', 1, 'code_debugging', 'The server sends every update as a named event, event: position-update, not the default message event. Which line explains why updateBusMarker never runs?', '{"language":"javascript","code":"const source = new EventSource(\"/transit/live-positions\");\nsource.addEventListener(\"message\", (event) => {\n  const position = JSON.parse(event.data);\n  updateBusMarker(position);\n});\nsource.onerror = () => {\n  console.log(\"SSE connection lost\");\n};","question":"The server sends every update as a named event, event: position-update, not the default message event. Which line explains why updateBusMarker never runs?"}'::jsonb, '{"requiredLineIds":["source.addEventListener(\"message\", (event) => {"]}'::jsonb),

  ('mission-be15-11-o1-c1', 'mission-be15-11-o1', 1, 'interactive_diagram', 'Put a well-behaved exponential-backoff reconnect strategy in order.', '{"diagramId":"reconnect-backoff","hotspots":[{"id":"connection_drops","label":"Connection drops","explanation":"Detected via a close event, an error, or a missed heartbeat."},{"id":"wait_short_delay","label":"Client waits a short initial delay","explanation":"Retrying instantly against a struggling service usually makes things worse, not better."},{"id":"attempt_reconnect","label":"Client attempts to reconnect","explanation":"A fresh connection attempt is made after the delay."},{"id":"double_delay_on_failure","label":"On failure, the delay roughly doubles, up to a cap","explanation":"Exponential backoff spaces out retries automatically as failures continue, instead of hammering the service."},{"id":"reset_delay_on_success","label":"On success, the delay resets to its initial value","explanation":"A healthy connection means the next drop, whenever it happens, should be retried quickly again."}],"task":"Put a well-behaved exponential-backoff reconnect strategy in order."}'::jsonb, '{"correctOrderIds":["connection_drops","wait_short_delay","attempt_reconnect","double_delay_on_failure","reset_delay_on_success"]}'::jsonb),
  ('mission-be15-11-o2-c1', 'mission-be15-11-o2', 1, 'drag_and_drop', 'Match each concept to what it actually does in detecting whether a connection is genuinely still alive.', '{"items":[{"id":"i1","text":"Heartbeat / ping frame"},{"id":"i2","text":"Pong reply"},{"id":"i3","text":"Heartbeat timeout window"},{"id":"i4","text":"TCP keepalive"}],"targets":[{"id":"t1","label":"A small application-level message sent periodically specifically to ask \"are you still there?\""},{"id":"t2","label":"The expected reply to a ping -- its arrival is what actually proves the other side is alive and responsive"},{"id":"t3","label":"The bounded time a sender waits for a pong before deciding, on its own, that the connection is dead"},{"id":"t4","label":"An OS-level keepalive mechanism that exists but is often disabled by default and, even enabled, can take minutes to hours to notice a dead peer -- too slow to trust on its own"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be15-12-o1-c1', 'mission-be15-12-o1', 1, 'multiple_choice', 'Diagnosis Alpha: "TCP itself will detect the dead connection and tell the server almost immediately -- we just need to trust the OS layer." Does this explain why the bus showed "on time" for eleven minutes?', '{"question":"Diagnosis Alpha: \"TCP itself will detect the dead connection and tell the server almost immediately -- we just need to trust the OS layer.\" Does this explain why the bus showed \"on time\" for eleven minutes?","options":[{"id":"a","text":"Yes -- TCP always notices a dead peer within seconds"},{"id":"b","text":"No -- TCP keepalive is often disabled by default, and even when enabled its default interval is commonly measured in hours, not seconds; on top of that, NATs and load balancers between the two ends can silently drop the connection without either OS ever seeing a reset or a close, so nothing at the TCP layer was guaranteed to notice quickly, or possibly ever"},{"id":"c","text":"Yes -- but only for WebSocket connections specifically, not other TCP connections"},{"id":"d","text":"Unknowable without seeing the server''s CPU usage"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be15-12-o2-c1', 'mission-be15-12-o2', 1, 'multiple_choice', 'Diagnosis Bravo: "The dashboard client just needs to retry connecting faster and more often." Does faster client-side reconnection, by itself, explain or fix the eleven-minute gap?', '{"question":"Diagnosis Bravo: \"The dashboard client just needs to retry connecting faster and more often.\" Does faster client-side reconnection, by itself, explain or fix the eleven-minute gap?","options":[{"id":"a","text":"Yes -- faster retries mean the client notices and reconnects within seconds"},{"id":"b","text":"No -- reconnecting faster only helps once the client has already realized the old connection is gone; if nothing ever tells it the connection died, a faster retry loop that never triggers changes nothing, and the dashboard was still showing stale \"on time\" data from the dead connection the whole time"},{"id":"c","text":"Yes -- exponential backoff was clearly the missing piece"},{"id":"d","text":"Unknowable without seeing the client''s retry code"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be15-12-o3-c1', 'mission-be15-12-o3', 1, 'multiple_choice', 'Diagnosis Charlie: "Increase the WebSocket library''s internal read-buffer timeout setting." Does that setting explain or fix the eleven-minute gap?', '{"question":"Diagnosis Charlie: \"Increase the WebSocket library''s internal read-buffer timeout setting.\" Does that setting explain or fix the eleven-minute gap?","options":[{"id":"a","text":"Yes -- a longer read-buffer timeout is exactly what liveness detection means"},{"id":"b","text":"No -- a read-buffer timeout governs how long the library waits for the next chunk of an in-progress read, not whether the connection itself is still alive; it is not an application-level \"are you still there\" check, and tuning it does not add any actual detection that was missing"},{"id":"c","text":"Yes -- this is the standard fix for every WebSocket disconnect issue"},{"id":"d","text":"Unknowable without seeing the buffer size"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be15-12-o4-c1', 'mission-be15-12-o4', 1, 'boss_encounter', 'Having ruled out all three, state the one safeguard that would have caught this the moment it happened.', '{"stages":[{"objectiveRef":"mission-be15-12-o1","label":"Diagnosis Alpha"},{"objectiveRef":"mission-be15-12-o2","label":"Diagnosis Bravo"},{"objectiveRef":"mission-be15-12-o3","label":"Diagnosis Charlie"}],"task":"Having ruled out all three, state the one safeguard that would have caught this the moment it happened: an application-level heartbeat -- a ping sent on a regular interval, with an enforced pong-or-timeout window -- so the feed declares a connection dead on its own schedule instead of waiting on TCP, a faster retry loop, or a buffer setting to notice for it."}'::jsonb, '{"requiredObjectiveIds":["mission-be15-12-o1","mission-be15-12-o2","mission-be15-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be15-01-o1-c1', 'orientation', 'Think about what changes for the code that makes the call, not what changes on the wire.', 10, 1),
  ('mission-be15-01-o1-c1', 'concept', 'A well-designed RPC call reads exactly like myService.getPosition(busId) -- no networking code visible at the call site.', 20, 2),
  ('mission-be15-01-o1-c1', 'solution', 'a -- RPC''s whole point is making a network call look like an ordinary function call to the code that makes it.', 30, 3),
  ('mission-be15-01-o2-c1', 'orientation', 'Two of these live on the client side of the wire, two live on the server side.', 10, 1),
  ('mission-be15-01-o2-c1', 'solution', 'Client stub -> looks local but packages and sends the call. Marshalling -> converts the call into bytes. Transport -> the network layer the bytes cross. Server skeleton -> unpacks the bytes and invokes the real method.', 20, 2),

  ('mission-be15-02-o1-c1', 'orientation', 'One of these lives in the schema file, one lives on the wire, one lives in generated code, one lives on the server object itself.', 10, 1),
  ('mission-be15-02-o1-c1', 'solution', 'message -> the typed data structure. field number -> the wire tag, not the name. service -> the collection of RPC methods. generated stub code -> what protoc produces so nobody hand-writes serialization.', 20, 2),
  ('mission-be15-02-o2-c1', 'orientation', 'Field numbers are what protobuf actually encodes on the wire -- names never leave the .proto file.', 10, 1),
  ('mission-be15-02-o2-c1', 'concept', 'Two fields with the same number are indistinguishable once serialized; a reader has no way to know which one a given byte range belongs to.', 20, 2),
  ('mission-be15-02-o2-c1', 'solution', 'double longitude = 2; reuses field number 2, already claimed by latitude -- that collision is the bug, not the field name.', 30, 3),

  ('mission-be15-03-o1-c1', 'orientation', 'HTTP/2 is doing real work here, not just being a label.', 10, 1),
  ('mission-be15-03-o1-c1', 'solution', 'b -- protobuf defines the contract, generated code implements it, HTTP/2 carries it.', 20, 2),
  ('mission-be15-03-o2-c1', 'orientation', 'Ask which side is doing the repeating: the requester, the responder, both, or neither.', 10, 1),
  ('mission-be15-03-o2-c1', 'solution', 'Unary -> one/one. Server streaming -> one request, many responses. Client streaming -> many requests, one response. Bidirectional -> many/many, independently.', 20, 2),

  ('mission-be15-04-o1-c1', 'orientation', 'The word stream appearing anywhere in the signature rules a line out immediately.', 10, 1),
  ('mission-be15-04-o1-c1', 'solution', 'rpc GetCurrentPosition(VehicleRequest) returns (VehiclePosition); -- no stream keyword on either side, one request, one response.', 20, 2),
  ('mission-be15-04-o2-c1', 'orientation', 'ev3 is a symptom of the real problem, not the problem itself.', 10, 1),
  ('mission-be15-04-o2-c1', 'concept', 'A unary call has no concept of "and then send me more later" -- once it returns, the call is over.', 20, 2),
  ('mission-be15-04-o2-c1', 'solution', 'ev2 -- the requirement is continuous movement, and a call that ends the instant it answers cannot represent that without being re-invoked over and over, which is exactly the workaround ev3 describes.', 30, 3),

  ('mission-be15-05-o1-c1', 'orientation', 'Nothing can be sent on a stream that was never opened.', 10, 1),
  ('mission-be15-05-o1-c1', 'concept', 'A server-streaming call still starts exactly like a unary call -- the difference is entirely in what happens after.', 20, 2),
  ('mission-be15-05-o1-c1', 'solution', 'Client sends the request, server opens the stream, server sends messages as they happen, server closes the stream when done.', 30, 3),
  ('mission-be15-05-o2-c1', 'orientation', 'A single long-lived call is fundamentally different from many short repeated calls, even if both eventually deliver similar data.', 10, 1),
  ('mission-be15-05-o2-c1', 'solution', 'ev1 -- one open call receiving a continuous sequence of messages is exactly what server streaming was built for; ev3 describes the polling problem it replaces.', 20, 2),

  ('mission-be15-06-o1-c1', 'orientation', 'Ask, for each scenario, who is sending more than once: the client, the server, both, or neither.', 10, 1),
  ('mission-be15-06-o1-c1', 'solution', 'i1 (many requests, one final response) -> client streaming. i2 (both sides, freely) -> bidirectional. i3 (one/one) -> unary. i4 (one request, many responses) -> server streaming.', 20, 2),
  ('mission-be15-06-o2-c1', 'orientation', 'Independent is the operative word -- think of two people on a phone call, not two people passing a single microphone.', 10, 1),
  ('mission-be15-06-o2-c1', 'solution', 'b -- the two directions are genuinely independent; any ordering discipline has to be built by the application, gRPC does not impose one.', 20, 2),

  ('mission-be15-07-o1-c1', 'orientation', 'A slot doesn''t free itself just because nothing is coming down it.', 10, 1),
  ('mission-be15-07-o1-c1', 'concept', 'Without an explicit deadline, a client will wait for a response indefinitely by default -- there is no built-in limit.', 20, 2),
  ('mission-be15-07-o1-c1', 'solution', 'ev1 -- no deadline was ever set on this call, so the client (and the pooled resource it is holding) waited indefinitely with nothing forcing it to give up.', 30, 3),
  ('mission-be15-07-o2-c1', 'orientation', 'One of these is a single specific mechanism; the rest are things that specific mechanism is commonly used to carry.', 10, 1),
  ('mission-be15-07-o2-c1', 'solution', 'Deadline -> the hard time limit. Metadata -> the general header-like mechanism. Auth token and trace ID -> two common things carried inside that mechanism.', 20, 2),

  ('mission-be15-08-o1-c1', 'orientation', 'Think about who controls both ends of the call, and how flexible the shape of the response needs to be.', 10, 1),
  ('mission-be15-08-o1-c1', 'solution', 'i1 -> GraphQL (flexible shape). i2 -> REST (simple, cacheable). i3 -> gRPC unary (internal, fast). i4 -> gRPC server streaming (internal, continuous).', 20, 2),
  ('mission-be15-08-o2-c1', 'orientation', 'This is not about gRPC being unsafe or slow -- it is about what a browser''s networking stack is actually able to construct.', 10, 1),
  ('mission-be15-08-o2-c1', 'solution', 'b -- browsers cannot speak raw HTTP/2 framing and binary protobuf directly the way a generated gRPC client can, so a browser-facing translation layer (grpc-web plus a proxy) has to sit in front of it.', 20, 2),

  ('mission-be15-09-o1-c1', 'orientation', 'A protocol cannot switch until both sides have agreed to switch.', 10, 1),
  ('mission-be15-09-o1-c1', 'concept', 'A WebSocket never opens a second connection -- it repurposes the one already used for the initial HTTP request.', 20, 2),
  ('mission-be15-09-o1-c1', 'solution', 'GET with an Upgrade header, then 101 Switching Protocols, then free full-duplex frames both ways, then an explicit close frame.', 30, 3),
  ('mission-be15-09-o2-c1', 'orientation', 'Not every device or piece of network equipment between two endpoints promises to tell either side when it silently drops a connection.', 10, 1),
  ('mission-be15-09-o2-c1', 'concept', 'A phone losing signal, a NAT gateway timing out an idle mapping, or a load balancer dropping a connection can all vanish a connection without ever sending a proper close frame to either side.', 20, 2),
  ('mission-be15-09-o2-c1', 'solution', 'ev1 -- a mobile network, a load balancer, and a NAT gateway all sit between the two ends, and any one of them can drop a connection silently, with neither the client nor the server ever seeing a close frame.', 30, 3),

  ('mission-be15-10-o1-c1', 'orientation', 'Ask whether the browser side of this feed ever needs to send anything back on the same connection.', 10, 1),
  ('mission-be15-10-o1-c1', 'solution', 'b -- since the browser only ever listens, SSE''s simplicity and free automatic reconnection make it the better fit than a full-duplex WebSocket the app does not use.', 20, 2),
  ('mission-be15-10-o2-c1', 'orientation', 'EventSource listens for a specific event name unless told otherwise, and the default it listens for is not the only kind of event a server can send.', 10, 1),
  ('mission-be15-10-o2-c1', 'concept', 'A named SSE event (event: position-update) never fires generic "message" listeners -- it needs its own addEventListener("position-update", ...) to be heard.', 20, 2),
  ('mission-be15-10-o2-c1', 'solution', 'source.addEventListener("message", (event) => { -- listens for the default message event, but the server is sending a differently-named event entirely, so this handler never fires.', 30, 3),

  ('mission-be15-11-o1-c1', 'orientation', 'Nothing can be retried before it has actually failed.', 10, 1),
  ('mission-be15-11-o1-c1', 'concept', 'Reconnecting instantly, every time, against a service that is already struggling, is how a brief hiccup turns into a pile-on.', 20, 2),
  ('mission-be15-11-o1-c1', 'solution', 'Connection drops, wait an initial short delay, attempt to reconnect, double the delay on continued failure (up to a cap), reset the delay once a connection succeeds again.', 30, 3),
  ('mission-be15-11-o2-c1', 'orientation', 'Two of these are messages exchanged over the wire. Two of these are about how long to wait and what mechanism is doing the waiting.', 10, 1),
  ('mission-be15-11-o2-c1', 'concept', 'A ping without an enforced timeout is just a message nobody is required to answer in any bounded time -- the timeout is what actually turns silence into a verdict.', 20, 2),
  ('mission-be15-11-o2-c1', 'solution', 'Heartbeat/ping -> the "are you there" message. Pong -> the proof-of-life reply. Timeout window -> the bounded wait before declaring death. TCP keepalive -> the OS-level mechanism that is too slow/unreliable to depend on alone.', 30, 3),

  ('mission-be15-12-o1-c1', 'orientation', 'Ask what TCP keepalive actually defaults to, if it is even turned on at all.', 10, 1),
  ('mission-be15-12-o1-c1', 'solution', 'b -- TCP-level detection is neither guaranteed to be enabled nor fast, and intermediate network equipment can swallow a disconnect entirely.', 20, 2),
  ('mission-be15-12-o2-c1', 'orientation', 'A retry loop only ever runs after something has told the client to retry.', 10, 1),
  ('mission-be15-12-o2-c1', 'solution', 'b -- reconnecting faster doesn''t help if nothing ever detects the drop in the first place; the client kept trusting a connection that was already dead.', 20, 2),
  ('mission-be15-12-o3-c1', 'orientation', 'A read-buffer timeout is about parsing bytes already arriving, not about deciding whether any more are coming.', 10, 1),
  ('mission-be15-12-o3-c1', 'solution', 'b -- that setting has nothing to do with detecting a silently dead peer; it is an unrelated knob.', 20, 2),
  ('mission-be15-12-o4-c1', 'orientation', 'Every mission this Act taught you at least one piece of this answer -- Mission 11 taught you its name directly.', 15, 1),
  ('mission-be15-12-o4-c1', 'solution', 'An application-level heartbeat/ping-pong mechanism with an enforced timeout: send a ping on a fixed interval, require a pong within a bounded window, and declare the connection dead the moment that window closes -- independent of TCP, retries, or any buffer setting.', 25, 2);
